insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('b6967e2a-ad84-43d7-9b70-7f85ed0e2a44', '4014ed40-e4df-4d87-b214-894666def043', null, 'topic'::public.curated_course_node_type, 'Process Dynamics Modeling and Dynamic Balances', 'Students learn how chemical processes change with time, and how conservation laws become dynamic models for tanks, reactors, heat exchangers, and separation units.', 0),
  ('4391a4b6-5606-480d-85d7-8462a758a1fe', '4014ed40-e4df-4d87-b214-894666def043', 'b6967e2a-ad84-43d7-9b70-7f85ed0e2a44', 'subtopic'::public.curated_course_node_type, 'Dynamic conservation laws', 'Process behavior is viewed as accumulation plus flows, reactions, and heat effects rather than as isolated equations.', 0),
  ('ec7f08b4-c402-477d-9813-a7b4e9a5e955', '4014ed40-e4df-4d87-b214-894666def043', '4391a4b6-5606-480d-85d7-8462a758a1fe', 'concept'::public.curated_course_node_type, 'Total and component mass balances', null, 0),
  ('e5503ac5-e42e-467f-9040-19137b174be5', '4014ed40-e4df-4d87-b214-894666def043', '4391a4b6-5606-480d-85d7-8462a758a1fe', 'concept'::public.curated_course_node_type, 'Energy balances with heat transfer and reaction', null, 1),
  ('d751c63a-9ad2-4774-a291-e30737c5c9b8', '4014ed40-e4df-4d87-b214-894666def043', '4391a4b6-5606-480d-85d7-8462a758a1fe', 'concept'::public.curated_course_node_type, 'Degrees of freedom and simplifying assumptions', null, 2),
  ('3b624be2-881f-4aaa-bc63-702c9080a672', '4014ed40-e4df-4d87-b214-894666def043', 'b6967e2a-ad84-43d7-9b70-7f85ed0e2a44', 'subtopic'::public.curated_course_node_type, 'Unit-operation models', 'Students learn how the same modeling pattern appears across tanks, reactors, heat exchangers, and separation equipment.', 1),
  ('077c2dd0-7069-404e-8532-22e0e9247d0f', '4014ed40-e4df-4d87-b214-894666def043', '3b624be2-881f-4aaa-bc63-702c9080a672', 'concept'::public.curated_course_node_type, 'Mixing tanks and surge vessels', null, 0),
  ('4f17b454-2292-4268-af19-818099aba2e4', '4014ed40-e4df-4d87-b214-894666def043', '3b624be2-881f-4aaa-bc63-702c9080a672', 'concept'::public.curated_course_node_type, 'CSTRs and batch reactors', null, 1),
  ('d32950e8-905a-4685-ab33-47a8267b454d', '4014ed40-e4df-4d87-b214-894666def043', '3b624be2-881f-4aaa-bc63-702c9080a672', 'concept'::public.curated_course_node_type, 'Heat exchangers, jackets, and coils', null, 2),
  ('c4a24ab0-b5a1-4296-b2df-5ec9a80019e2', '4014ed40-e4df-4d87-b214-894666def043', 'b6967e2a-ad84-43d7-9b70-7f85ed0e2a44', 'subtopic'::public.curated_course_node_type, 'Process variables and disturbances', 'This subtopic clarifies what can be measured, what can be manipulated, and what arrives from outside the loop.', 2),
  ('7eb6ad89-1974-426d-9b11-054462a71cb1', '4014ed40-e4df-4d87-b214-894666def043', 'c4a24ab0-b5a1-4296-b2df-5ec9a80019e2', 'concept'::public.curated_course_node_type, 'Controlled variables', null, 0),
  ('ef5cc36d-0d47-47a0-9066-73ec3d2950b5', '4014ed40-e4df-4d87-b214-894666def043', 'c4a24ab0-b5a1-4296-b2df-5ec9a80019e2', 'concept'::public.curated_course_node_type, 'Manipulated variables', null, 1),
  ('752a2fd7-08ce-4c56-a6d4-7faab10ac1fd', '4014ed40-e4df-4d87-b214-894666def043', 'c4a24ab0-b5a1-4296-b2df-5ec9a80019e2', 'concept'::public.curated_course_node_type, 'Load disturbances and unmeasured inputs', null, 2),
  ('cf042617-950c-494c-9bc8-18d1edfe7615', '4014ed40-e4df-4d87-b214-894666def043', null, 'topic'::public.curated_course_node_type, 'Laplace Transforms and Linearization for Process Control', 'This module builds the mathematical bridge between nonlinear process equations and the linear input-output models used in classical control analysis.', 1),
  ('03b6dd66-8a9f-43c9-9c6c-9350c0e85632', '4014ed40-e4df-4d87-b214-894666def043', 'cf042617-950c-494c-9bc8-18d1edfe7615', 'subtopic'::public.curated_course_node_type, 'Deviation variables', 'Deviation variables keep the focus on changes from an operating point, which is how many industrial controllers are designed.', 0),
  ('edbc75bb-d73d-4d76-a648-83404a8bf838', '4014ed40-e4df-4d87-b214-894666def043', '03b6dd66-8a9f-43c9-9c6c-9350c0e85632', 'concept'::public.curated_course_node_type, 'Nominal operating points', null, 0),
  ('9d7026bf-7e3d-43e1-9976-e310ab6b89a9', '4014ed40-e4df-4d87-b214-894666def043', '03b6dd66-8a9f-43c9-9c6c-9350c0e85632', 'concept'::public.curated_course_node_type, 'Input and output perturbations', null, 1),
  ('8acbb13f-d0e0-44b2-a6cf-9d88af4a7189', '4014ed40-e4df-4d87-b214-894666def043', '03b6dd66-8a9f-43c9-9c6c-9350c0e85632', 'concept'::public.curated_course_node_type, 'Physical meaning of zero initial deviation', null, 2),
  ('2fc2c683-c9f9-4a5e-a8d7-820e2e0bfce7', '4014ed40-e4df-4d87-b214-894666def043', 'cf042617-950c-494c-9bc8-18d1edfe7615', 'subtopic'::public.curated_course_node_type, 'Linearization', 'Students learn how to approximate nonlinear equations so classical control tools can be applied responsibly.', 1),
  ('d1475575-c7e3-4b52-9b1b-5aaef3ec0209', '4014ed40-e4df-4d87-b214-894666def043', '2fc2c683-c9f9-4a5e-a8d7-820e2e0bfce7', 'concept'::public.curated_course_node_type, 'Taylor-series first-order approximation', null, 0),
  ('203a7376-3afb-4715-8d34-87f65b079dcb', '4014ed40-e4df-4d87-b214-894666def043', '2fc2c683-c9f9-4a5e-a8d7-820e2e0bfce7', 'concept'::public.curated_course_node_type, 'Jacobian terms and sensitivity', null, 1),
  ('b2b260ad-79ef-4e5b-a7f1-638c3cdb4a55', '4014ed40-e4df-4d87-b214-894666def043', '2fc2c683-c9f9-4a5e-a8d7-820e2e0bfce7', 'concept'::public.curated_course_node_type, 'Limits of linear models', null, 2),
  ('685e134c-c4b1-49ed-a7d9-7d0d62279b6c', '4014ed40-e4df-4d87-b214-894666def043', 'cf042617-950c-494c-9bc8-18d1edfe7615', 'subtopic'::public.curated_course_node_type, 'Laplace-domain solution methods', 'The goal is to make dynamic response easier to solve and combine using algebraic relationships.', 2),
  ('7ec92f1b-17a8-4a4e-b218-ab438fd441cb', '4014ed40-e4df-4d87-b214-894666def043', '685e134c-c4b1-49ed-a7d9-7d0d62279b6c', 'concept'::public.curated_course_node_type, 'Transforming differential equations', null, 0),
  ('8966e2de-a746-422d-92a1-30802ede67bb', '4014ed40-e4df-4d87-b214-894666def043', '685e134c-c4b1-49ed-a7d9-7d0d62279b6c', 'concept'::public.curated_course_node_type, 'Initial conditions', null, 1),
  ('6309de1f-7afe-4c85-ad01-fae9e27712d7', '4014ed40-e4df-4d87-b214-894666def043', '685e134c-c4b1-49ed-a7d9-7d0d62279b6c', 'concept'::public.curated_course_node_type, 'Inverse transforms and response interpretation', null, 2),
  ('ec60b2e2-0f24-42b0-84ad-cbd6bcb625e5', '4014ed40-e4df-4d87-b214-894666def043', null, 'topic'::public.curated_course_node_type, 'Transfer Functions and Block-Diagram Models', 'Students convert process models into compact input-output relationships and learn how controllers, sensors, actuators, and processes connect in a control loop.', 2),
  ('078f660f-26bf-47d9-9242-21c107c893f8', '4014ed40-e4df-4d87-b214-894666def043', 'ec60b2e2-0f24-42b0-84ad-cbd6bcb625e5', 'subtopic'::public.curated_course_node_type, 'Transfer-function construction', 'Students learn to describe each plant element as an input-output block with gain and dynamics.', 0),
  ('f2eed0a8-9004-4c37-8965-16d5cb9239b1', '4014ed40-e4df-4d87-b214-894666def043', '078f660f-26bf-47d9-9242-21c107c893f8', 'concept'::public.curated_course_node_type, 'Process transfer functions', null, 0),
  ('99602585-6be6-4ed6-8234-4dc21d8d2dbc', '4014ed40-e4df-4d87-b214-894666def043', '078f660f-26bf-47d9-9242-21c107c893f8', 'concept'::public.curated_course_node_type, 'Measurement and transmitter dynamics', null, 1),
  ('8e98baea-acbb-4274-a5f2-2da35e23d6fa', '4014ed40-e4df-4d87-b214-894666def043', '078f660f-26bf-47d9-9242-21c107c893f8', 'concept'::public.curated_course_node_type, 'Valve and actuator dynamics', null, 2),
  ('efda66f6-8748-4316-a87c-4e891b5b2b74', '4014ed40-e4df-4d87-b214-894666def043', 'ec60b2e2-0f24-42b0-84ad-cbd6bcb625e5', 'subtopic'::public.curated_course_node_type, 'Block diagrams', 'Block diagrams make control-loop structure visible and help students reason about signal paths.', 1),
  ('792769d7-5384-4a56-b2d1-33a348b3c0b8', '4014ed40-e4df-4d87-b214-894666def043', 'efda66f6-8748-4316-a87c-4e891b5b2b74', 'concept'::public.curated_course_node_type, 'Summing junctions', null, 0),
  ('7c255553-6f38-4ff6-acd2-2a5f5861e593', '4014ed40-e4df-4d87-b214-894666def043', 'efda66f6-8748-4316-a87c-4e891b5b2b74', 'concept'::public.curated_course_node_type, 'Series, parallel, and feedback combinations', null, 1),
  ('862184c0-64b6-4af6-b1ef-54b2312abb98', '4014ed40-e4df-4d87-b214-894666def043', 'efda66f6-8748-4316-a87c-4e891b5b2b74', 'concept'::public.curated_course_node_type, 'Disturbance-entry points', null, 2),
  ('01ae9231-d83f-4145-85e4-f8070c77a6f7', '4014ed40-e4df-4d87-b214-894666def043', 'ec60b2e2-0f24-42b0-84ad-cbd6bcb625e5', 'subtopic'::public.curated_course_node_type, 'Closed-loop relationships', 'The gist is that controller behavior must be evaluated in the loop, not only as a standalone device.', 2),
  ('a9d9b65e-26fe-4c63-bd19-c7f42f87b0f3', '4014ed40-e4df-4d87-b214-894666def043', '01ae9231-d83f-4145-85e4-f8070c77a6f7', 'concept'::public.curated_course_node_type, 'Servo transfer functions', null, 0),
  ('f019dd23-5503-4638-9cf9-f1b7ab1867a5', '4014ed40-e4df-4d87-b214-894666def043', '01ae9231-d83f-4145-85e4-f8070c77a6f7', 'concept'::public.curated_course_node_type, 'Regulatory transfer functions', null, 1),
  ('192eb341-8f82-4a02-8e1c-f11d2db8e4cb', '4014ed40-e4df-4d87-b214-894666def043', '01ae9231-d83f-4145-85e4-f8070c77a6f7', 'concept'::public.curated_course_node_type, 'Sensitivity and complementary sensitivity', null, 2),
  ('3cee0b43-4ec2-499d-a141-e03b2a717496', '4014ed40-e4df-4d87-b214-894666def043', null, 'topic'::public.curated_course_node_type, 'First- and Second-Order Process Responses', 'This topic gives students the vocabulary for recognizing process behavior from step tests, data trends, and model parameters.', 3),
  ('e792abbb-92d2-4ae0-8c45-25e9c0ea5e2d', '4014ed40-e4df-4d87-b214-894666def043', '3cee0b43-4ec2-499d-a141-e03b2a717496', 'subtopic'::public.curated_course_node_type, 'First-order plus dead-time behavior', 'Many process units can be approximated well enough by gain, time constant, and delay for controller tuning.', 0),
  ('a70760ec-76a9-4ddc-8ca1-a4bd6b3a619e', '4014ed40-e4df-4d87-b214-894666def043', 'e792abbb-92d2-4ae0-8c45-25e9c0ea5e2d', 'concept'::public.curated_course_node_type, 'Process gain', null, 0),
  ('a02e45b4-9352-44ea-9867-f4879f1b2ecd', '4014ed40-e4df-4d87-b214-894666def043', 'e792abbb-92d2-4ae0-8c45-25e9c0ea5e2d', 'concept'::public.curated_course_node_type, 'Time constant', null, 1),
  ('7c48ec82-b1ee-49a6-93b2-c9579c9fec83', '4014ed40-e4df-4d87-b214-894666def043', 'e792abbb-92d2-4ae0-8c45-25e9c0ea5e2d', 'concept'::public.curated_course_node_type, 'Transportation and measurement dead time', null, 2),
  ('7de25f26-3488-4cfc-a1ba-48539b47423d', '4014ed40-e4df-4d87-b214-894666def043', '3cee0b43-4ec2-499d-a141-e03b2a717496', 'subtopic'::public.curated_course_node_type, 'Second-order behavior', 'Students learn to recognize underdamped, overdamped, and critically damped responses in process data.', 1),
  ('b9929c6b-12c1-483d-b54b-cc1dffd270f0', '4014ed40-e4df-4d87-b214-894666def043', '7de25f26-3488-4cfc-a1ba-48539b47423d', 'concept'::public.curated_course_node_type, 'Natural frequency', null, 0),
  ('288ded0c-6fd9-44ac-99b0-8c2e837aabac', '4014ed40-e4df-4d87-b214-894666def043', '7de25f26-3488-4cfc-a1ba-48539b47423d', 'concept'::public.curated_course_node_type, 'Damping ratio', null, 1),
  ('b1caf1b4-b4c9-40fc-9b78-7c03fe0e96df', '4014ed40-e4df-4d87-b214-894666def043', '7de25f26-3488-4cfc-a1ba-48539b47423d', 'concept'::public.curated_course_node_type, 'Overshoot and oscillation', null, 2),
  ('43e8aa61-078b-4be8-8528-e0e9b50521e6', '4014ed40-e4df-4d87-b214-894666def043', '3cee0b43-4ec2-499d-a141-e03b2a717496', 'subtopic'::public.curated_course_node_type, 'Nonstandard responses', 'Some real processes do not behave like simple lags, so students need warning signs for special treatment.', 2),
  ('51798bba-423d-4597-84df-c5e06c2a21c6', '4014ed40-e4df-4d87-b214-894666def043', '43e8aa61-078b-4be8-8528-e0e9b50521e6', 'concept'::public.curated_course_node_type, 'Integrating processes', null, 0),
  ('e9ba9bfb-7f2a-46ab-b2a0-0c105c8674b1', '4014ed40-e4df-4d87-b214-894666def043', '43e8aa61-078b-4be8-8528-e0e9b50521e6', 'concept'::public.curated_course_node_type, 'Inverse response', null, 1),
  ('e2616788-9191-435e-b6f6-18609f38f8e9', '4014ed40-e4df-4d87-b214-894666def043', '43e8aa61-078b-4be8-8528-e0e9b50521e6', 'concept'::public.curated_course_node_type, 'Multiple-lag approximations', null, 2),
  ('59df5f51-116a-44a5-90e6-351686c5ba6b', '4014ed40-e4df-4d87-b214-894666def043', null, 'topic'::public.curated_course_node_type, 'Feedback Control Loops and Closed-Loop Behavior', 'Students study the logic of feedback control: measure the process, compare it to a target, and take corrective action while managing tradeoffs.', 4),
  ('63419759-258b-4661-a78d-7dcf11a8c54d', '4014ed40-e4df-4d87-b214-894666def043', '59df5f51-116a-44a5-90e6-351686c5ba6b', 'subtopic'::public.curated_course_node_type, 'Feedback architecture', 'Students learn the basic closed-loop pattern used throughout process plants.', 0),
  ('8b20e0c2-80db-4370-9b22-845743336860', '4014ed40-e4df-4d87-b214-894666def043', '63419759-258b-4661-a78d-7dcf11a8c54d', 'concept'::public.curated_course_node_type, 'Controller, process, sensor, and final element', null, 0),
  ('df06b290-7902-4f12-a232-2a9415bdeb64', '4014ed40-e4df-4d87-b214-894666def043', '63419759-258b-4661-a78d-7dcf11a8c54d', 'concept'::public.curated_course_node_type, 'Negative feedback', null, 1),
  ('7b6d5bab-981b-498f-9cc6-519bb4d46c87', '4014ed40-e4df-4d87-b214-894666def043', '63419759-258b-4661-a78d-7dcf11a8c54d', 'concept'::public.curated_course_node_type, 'Manual versus automatic mode', null, 2),
  ('3817f1ae-8c2a-4a3a-bf8c-9308b86b1da3', '4014ed40-e4df-4d87-b214-894666def043', '59df5f51-116a-44a5-90e6-351686c5ba6b', 'subtopic'::public.curated_course_node_type, 'Performance measures', 'This subtopic gives students practical criteria for judging whether a loop is good enough.', 1),
  ('413b15c7-e7bf-434b-b03f-08258de037ff', '4014ed40-e4df-4d87-b214-894666def043', '3817f1ae-8c2a-4a3a-bf8c-9308b86b1da3', 'concept'::public.curated_course_node_type, 'Offset', null, 0),
  ('d17076bb-7ce8-459a-9107-d2e3ab3fe23a', '4014ed40-e4df-4d87-b214-894666def043', '3817f1ae-8c2a-4a3a-bf8c-9308b86b1da3', 'concept'::public.curated_course_node_type, 'Rise time and settling time', null, 1),
  ('0b406cdc-9fdd-4138-834b-43bf1c84014d', '4014ed40-e4df-4d87-b214-894666def043', '3817f1ae-8c2a-4a3a-bf8c-9308b86b1da3', 'concept'::public.curated_course_node_type, 'Overshoot and integrated error criteria', null, 2),
  ('f290c92d-8ef1-4b8c-999d-427658067112', '4014ed40-e4df-4d87-b214-894666def043', '59df5f51-116a-44a5-90e6-351686c5ba6b', 'subtopic'::public.curated_course_node_type, 'Disturbance rejection', 'Regulatory control is central in chemical plants because production must remain stable despite changing loads.', 2),
  ('0f6ab58d-30fa-47bd-8ef1-74cb0c7afc7b', '4014ed40-e4df-4d87-b214-894666def043', 'f290c92d-8ef1-4b8c-999d-427658067112', 'concept'::public.curated_course_node_type, 'Load changes', null, 0),
  ('038504cb-dba8-44d9-a41d-95c2388191e1', '4014ed40-e4df-4d87-b214-894666def043', 'f290c92d-8ef1-4b8c-999d-427658067112', 'concept'::public.curated_course_node_type, 'Setpoint tracking', null, 1),
  ('e61ae426-4db1-4165-aef8-3c06041cfffa', '4014ed40-e4df-4d87-b214-894666def043', 'f290c92d-8ef1-4b8c-999d-427658067112', 'concept'::public.curated_course_node_type, 'Tradeoffs between speed and robustness', null, 2),
  ('8160fcb4-cfd2-4730-b57d-d62b9573cee6', '4014ed40-e4df-4d87-b214-894666def043', null, 'topic'::public.curated_course_node_type, 'PID Controllers and Controller Tuning', 'The core industrial controller is introduced as a practical design tool whose proportional, integral, and derivative modes shape loop behavior.', 5),
  ('90feaa0b-f69e-4a74-84b9-be619fb8e0b0', '4014ed40-e4df-4d87-b214-894666def043', '8160fcb4-cfd2-4730-b57d-d62b9573cee6', 'subtopic'::public.curated_course_node_type, 'PID modes', 'Students learn what each controller mode contributes to speed, offset removal, and damping.', 0),
  ('67b005d4-8b0e-4147-b395-b3fd3921fe07', '4014ed40-e4df-4d87-b214-894666def043', '90feaa0b-f69e-4a74-84b9-be619fb8e0b0', 'concept'::public.curated_course_node_type, 'Proportional gain', null, 0),
