  ('fc1752c2-d990-4f77-a35b-ccb1b4d9f17c', '4014ed40-e4df-4d87-b214-894666def043', '90feaa0b-f69e-4a74-84b9-be619fb8e0b0', 'concept'::public.curated_course_node_type, 'Derivative action', null, 2),
