  ('0d8743a4-4289-45b6-8ec0-50ea7a72def5', '4014ed40-e4df-4d87-b214-894666def043', '2fbac51e-57c0-44d8-b80d-9fa395eb76ab', 'concept'::public.curated_course_node_type, 'Characteristic equation', null, 0),
