  ('3dd51e98-229c-46d3-8824-1219816e4670', '4014ed40-e4df-4d87-b214-894666def043', null, 'topic'::public.curated_course_node_type, 'Cascade, Feedforward, Ratio, and Multivariable Control', 'This module extends beyond single-loop feedback into common industrial strategies for faster disturbance rejection and coordinated plant operation.', 8),
  ('8e630731-d49a-48e8-aa38-2c4e89379302', '4014ed40-e4df-4d87-b214-894666def043', '3dd51e98-229c-46d3-8824-1219816e4670', 'subtopic'::public.curated_course_node_type, 'Cascade control', 'Cascade control uses a fast inner loop to reduce disturbances before they reach the primary controlled variable.', 0),
  ('22832386-e091-48ec-b558-4450fb7cd5a3', '4014ed40-e4df-4d87-b214-894666def043', '8e630731-d49a-48e8-aa38-2c4e89379302', 'concept'::public.curated_course_node_type, 'Primary and secondary variables', null, 0),
