  ('6c19dd3c-ab11-40d2-bd93-c49d9cb357c0', '4014ed40-e4df-4d87-b214-894666def043', '3dd51e98-229c-46d3-8824-1219816e4670', 'subtopic'::public.curated_course_node_type, 'Feedforward and ratio control', 'Students learn how to act on measured disturbances before feedback error appears.', 1),
