  ('0efac8a5-cdf6-4fad-b9a0-9762ad4b9cf9', '4014ed40-e4df-4d87-b214-894666def043', null, 'topic'::public.curated_course_node_type, 'Process Instrumentation, Sensors, Actuators, and Final Control Elements', 'Control quality depends on field hardware, so students learn how measurements, valves, transmitters, and actuators shape real loop performance.', 9),
