  ('d3834e85-03f5-400f-80b3-6fe611be4505', '4014ed40-e4df-4d87-b214-894666def043', 'ba5ae7cc-e7c6-4a0b-9769-ebb268f1e62a', 'concept'::public.curated_course_node_type, 'Flow, level, pressure, and temperature sensors', null, 0),
