  ('5deadbe1-5d2f-4b6e-9157-096a14180f26', '4014ed40-e4df-4d87-b214-894666def043', 'f2c4b52c-f04e-4dda-8fcd-dac6c62296ba', 'concept'::public.curated_course_node_type, 'Dynamic model setup', null, 0),
