  ('5af229a3-b306-4d8f-92d3-1b71398de671', '4014ed40-e4df-4d87-b214-894666def043', '27cca492-56de-47d1-854e-ea23b99323d4', 'concept'::public.curated_course_node_type, 'Alarm philosophy', null, 0),
